import java.nio.file.Path;
import java.time.Instant;
import jdk.jfr.consumer.RecordedClass;
import jdk.jfr.consumer.RecordedClassLoader;
import jdk.jfr.consumer.RecordedEvent;
import jdk.jfr.consumer.RecordedFrame;
import jdk.jfr.consumer.RecordedMethod;
import jdk.jfr.consumer.RecordedStackTrace;
import jdk.jfr.consumer.RecordedThread;
import jdk.jfr.consumer.RecordingFile;

public class RawJfrFrames {
    public static void main(String[] args) throws Exception {
        Instant start = Instant.ofEpochMilli(Long.parseLong(args[1]));
        Instant end = Instant.ofEpochMilli(Long.parseLong(args[2]));
        int anomalous = 0;
        int memory = 0;
        long scanned = 0;
        try (RecordingFile recording = new RecordingFile(Path.of(args[0]))) {
            while (recording.hasMoreEvents()) {
                RecordedEvent event = recording.readEvent();
                scanned++;
                if (event.getStartTime().isBefore(start) || !event.getStartTime().isBefore(end)) continue;
                String kind = event.getEventType().getName();
                if (!kind.equals("jdk.ExecutionSample") && !kind.equals("jdk.ObjectAllocationSample")) continue;
                RecordedStackTrace trace = event.getStackTrace();
                if (trace == null) continue;
                boolean baos = false, recordAdd = false, memoryOutput = false;
                for (RecordedFrame frame : trace.getFrames()) {
                    RecordedMethod method = frame.getMethod();
                    String name = method.getType().getName();
                    baos |= name.equals("java.io.ByteArrayOutputStream");
                    recordAdd |= name.equals("org.eclipse.rdf4j.sail.lmdb.LmdbBackupRecordBuffer")
                            && method.getName().equals("add");
                    memoryOutput |= name.equals("org.eclipse.rdf4j.sail.lmdb.LmdbBackupRecordBuffer$MemoryOutput")
                            && method.getName().equals("toByteArray");
                }
                boolean printAnomaly = anomalous < 3 && kind.equals("jdk.ExecutionSample") && baos && recordAdd;
                boolean printMemory = memory == 0 && kind.equals("jdk.ObjectAllocationSample") && memoryOutput;
                if (!printAnomaly && !printMemory) continue;
                if (printAnomaly) anomalous++;
                if (printMemory) memory++;
                RecordedThread thread = event.hasField("sampledThread") ? event.getThread("sampledThread") : event.getThread();
                System.out.printf("EVENT kind=%s time=%s thread=%s anomaly=%s memoryOutput=%s truncated=%s%n",
                        kind, event.getStartTime(), thread == null ? "<none>" : thread.getJavaName(),
                        printAnomaly, printMemory, trace.isTruncated());
                int depth = 0;
                for (RecordedFrame frame : trace.getFrames()) {
                    RecordedMethod method = frame.getMethod();
                    RecordedClass type = method.getType();
                    RecordedClassLoader loader = type.getClassLoader();
                    String loaderType = loader == null || loader.getType() == null ? "<null>" : loader.getType().getName();
                    Object methodId = method.hasField("id") ? method.getValue("id") : "<not exposed>";
                    System.out.printf("%03d %s.%s descriptor=%s line=%d bci=%d frameType=%s classId=%d methodId=%s loaderName=%s loaderType=%s%n",
                            depth++, type.getName(), method.getName(), method.getDescriptor(), frame.getLineNumber(),
                            frame.getBytecodeIndex(), frame.getType(), type.getId(), methodId,
                            loader == null ? "<null>" : loader.getName(), loaderType);
                }
                if (anomalous == 3 && memory == 1) break;
            }
        }
        System.out.printf("SUMMARY scanned=%d anomalousExecutionEvents=%d memoryOutputAllocationEvents=%d%n",
                scanned, anomalous, memory);
        if (anomalous != 3 || memory != 1) throw new IllegalStateException("Expected raw events were not found");
    }
}

