// Some portions generated by Codex
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import jdk.jfr.consumer.RecordedClass;
import jdk.jfr.consumer.RecordedEvent;
import jdk.jfr.consumer.RecordedFrame;
import jdk.jfr.consumer.RecordedStackTrace;
import jdk.jfr.consumer.RecordedThread;
import jdk.jfr.consumer.RecordingFile;

/** Streaming, phase-filtered JFR aggregation; never expands a recording into per-event JSON. */
public final class CompactJfr {

	private static final Set<String> STACK_EVENTS = Set.of("jdk.ExecutionSample", "jdk.NativeMethodSample",
			"jdk.ObjectAllocationSample", "jdk.ThreadPark", "jdk.JavaMonitorEnter", "jdk.JavaMonitorWait",
			"jdk.FileRead", "jdk.FileWrite", "jdk.FileForce");
	private static final Set<String> SUMMARY_EVENTS = Set.of("jdk.GarbageCollection", "jdk.GCPhasePause",
			"jdk.Compilation", "jdk.CompilerPhase", "jdk.Deoptimization", "jdk.SafepointBegin",
			"jdk.ExecuteVMOperation", "jdk.ThreadCPULoad", "jdk.CPULoad");

	private CompactJfr() {
	}

	public static void main(String[] args) throws Exception {
		if (args.length != 5) {
			throw new IllegalArgumentException("recording.jfr startEpochMillis endEpochMillis transactions output.json");
		}
		Path recording = Path.of(args[0]);
		Instant start = Instant.ofEpochMilli(Long.parseLong(args[1]));
		Instant end = Instant.ofEpochMilli(Long.parseLong(args[2]));
		long transactions = Long.parseLong(args[3]);
		Map<String, Long> allEvents = new LinkedHashMap<>();
		Map<String, Long> measuredEvents = new LinkedHashMap<>();
		Map<String, Integer> frameIds = new LinkedHashMap<>();
		Map<Key, Statistics> stacks = new LinkedHashMap<>();
		Map<String, Statistics> summary = new LinkedHashMap<>();
		List<Map<String, Object>> cpu = new ArrayList<>();
		try (RecordingFile input = new RecordingFile(recording)) {
			while (input.hasMoreEvents()) {
				RecordedEvent event = input.readEvent();
				String type = event.getEventType().getName();
				allEvents.merge(type, 1L, Long::sum);
				Instant eventStart = event.getStartTime();
				Instant eventEnd = event.getEndTime();
				if (eventStart.compareTo(end) >= 0 || eventEnd.compareTo(start) < 0) {
					continue;
				}
				measuredEvents.merge(type, 1L, Long::sum);
				Instant clippedStart = eventStart.isBefore(start) ? start : eventStart;
				Instant clippedEnd = eventEnd.isAfter(end) ? end : eventEnd;
				long duration = Duration.between(clippedStart, clippedEnd).toNanos();
				RecordedThread recordedThread = event.hasField("sampledThread") ? event.getThread("sampledThread")
						: event.hasField("eventThread") ? event.getThread() : null;
				String thread = recordedThread == null ? "<none>" : recordedThread.getJavaName();
				if (STACK_EVENTS.contains(type)) {
					List<Integer> frames = new ArrayList<>();
					RecordedStackTrace trace = event.getStackTrace();
					if (trace != null) {
						for (RecordedFrame frame : trace.getFrames()) {
							String text = frame.getMethod().getType().getName() + "." + frame.getMethod().getName()
									+ ":" + frame.getLineNumber() + ":" + frame.getType();
							frames.add(frameIds.computeIfAbsent(text, ignored -> frameIds.size()));
						}
					}
					String detail = "";
					for (String field : List.of("objectClass", "monitorClass", "parkedClass")) {
						if (event.hasField(field)) {
							RecordedClass clazz = event.getClass(field);
							detail = clazz == null ? "<none>" : clazz.getName();
							break;
						}
					}
					String state = event.hasField("state") ? event.getString("state") : "";
					Key key = new Key(type, thread, detail, state, frames);
					Statistics statistics = stacks.computeIfAbsent(key, ignored -> new Statistics());
					statistics.count++;
					statistics.duration += duration;
					if (event.hasField("weight")) {
						statistics.weight += event.getLong("weight");
					}
				} else if (SUMMARY_EVENTS.contains(type)) {
					Statistics statistics = summary.computeIfAbsent(type + "/" + thread, ignored -> new Statistics());
					statistics.count++;
					statistics.duration += duration;
					if (type.equals("jdk.ThreadCPULoad") || type.equals("jdk.CPULoad")) {
						Map<String, Object> sample = new LinkedHashMap<>();
						sample.put("event", type);
						sample.put("thread", thread);
						sample.put("time_epoch_millis", eventStart.toEpochMilli());
						for (String field : List.of("user", "system", "jvmUser", "jvmSystem", "machineTotal")) {
							if (event.hasField(field)) {
								sample.put(field, event.getFloat(field));
							}
						}
						cpu.add(sample);
					}
				}
			}
		}
		List<Map<String, Object>> compactStacks = new ArrayList<>();
		for (Map.Entry<Key, Statistics> entry : stacks.entrySet()) {
			Key key = entry.getKey();
			Map<String, Object> row = new LinkedHashMap<>();
			row.put("event", key.event);
			row.put("thread", key.thread);
			row.put("detail", key.detail);
			row.put("state", key.state);
			row.put("frames", key.frames);
			row.put("count", entry.getValue().count);
			row.put("weight", entry.getValue().weight);
			row.put("duration_nanos", entry.getValue().duration);
			compactStacks.add(row);
		}
		Map<String, Object> output = new LinkedHashMap<>();
		output.put("recording", recording.toAbsolutePath().toString());
		output.put("recording_bytes", Files.size(recording));
		output.put("start_epoch_millis", start.toEpochMilli());
		output.put("end_epoch_millis", end.toEpochMilli());
		output.put("transactions", transactions);
		output.put("all_event_counts", allEvents);
		output.put("measurement_event_counts", measuredEvents);
		output.put("frames", new ArrayList<>(frameIds.keySet()));
		output.put("stacks", compactStacks);
		Map<String, Object> summaries = new LinkedHashMap<>();
		for (Map.Entry<String, Statistics> entry : summary.entrySet()) {
			summaries.put(entry.getKey(), Map.of("count", entry.getValue().count,
					"duration_nanos", entry.getValue().duration));
		}
		output.put("summaries", summaries);
		output.put("cpu_samples", cpu);
		try (BufferedWriter writer = Files.newBufferedWriter(Path.of(args[4]))) {
			json(writer, output);
			writer.newLine();
		}
		System.out.printf("%s: measured %d events, %d stack groups, %d frames%n", recording,
				measuredEvents.values().stream().mapToLong(Long::longValue).sum(), stacks.size(), frameIds.size());
	}

	private static void json(BufferedWriter writer, Object value) throws IOException {
		if (value == null) {
			writer.write("null");
		} else if (value instanceof Map<?, ?> map) {
			writer.write('{');
			boolean first = true;
			for (Map.Entry<?, ?> entry : map.entrySet()) {
				if (!first) {
					writer.write(',');
				}
				first = false;
				json(writer, entry.getKey().toString());
				writer.write(':');
				json(writer, entry.getValue());
			}
			writer.write('}');
		} else if (value instanceof Iterable<?> iterable) {
			writer.write('[');
			boolean first = true;
			for (Object item : iterable) {
				if (!first) {
					writer.write(',');
				}
				first = false;
				json(writer, item);
			}
			writer.write(']');
		} else if (value instanceof Number || value instanceof Boolean) {
			writer.write(value.toString());
		} else {
			writer.write('"');
			String text = value.toString();
			for (int i = 0; i < text.length(); i++) {
				char character = text.charAt(i);
				if (character == '"' || character == '\\') {
					writer.write('\\');
					writer.write(character);
				} else if (character < 0x20) {
					writer.write(String.format("\\u%04x", (int) character));
				} else {
					writer.write(character);
				}
			}
			writer.write('"');
		}
	}

	private record Key(String event, String thread, String detail, String state, List<Integer> frames) {
	}

	private static final class Statistics {
		long count;
		long weight;
		long duration;
	}
}

