import collections
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent / "candidate-capture-fresh-profile"
analysis = json.loads((ROOT / "profile-analysis.json").read_text())
output = []
for condition in analysis["conditions"]:
    name = condition["condition"]
    profile = json.loads((ROOT / f"{ROOT.name}-n100-synctrue-{name}-p1/measurement-compact.json").read_text())
    names = profile["frames"]
    operations = collections.Counter()
    components = collections.Counter()
    thread_totals = collections.Counter()
    background_self = collections.defaultdict(collections.Counter)
    operation_allocations = collections.Counter()
    for sample in profile["stacks"]:
        frames = [names[index].split(":")[0] for index in sample["frames"]]
        thread, event = sample["thread"], sample["event"]
        thread_totals[(thread, event)] += sample["count"]
        if thread != "main":
            if event == "jdk.ExecutionSample" and frames:
                background_self[thread][frames[0]] += sample["count"]
            continue
        backup = any(("Backup" in frame or "backup" in frame) and "ThroughputBenchmark" not in frame
                     for frame in frames)
        if not backup:
            continue
        operation = ("addition" if any("queueBackupAdd" in frame for frame in frames)
                     else "native_removal" if any("addNativeStatement" in frame for frame in frames)
                     and any("removeStatements" in frame for frame in frames)
                     else "native_capture_other" if any("addNativeStatement" in frame for frame in frames)
                     else "commit_or_other")
        if event == "jdk.ObjectAllocationSample":
            operation_allocations[operation] += sample["weight"]
        if event != "jdk.ExecutionSample":
            continue
        operations[operation] += sample["count"]
        patterns = {
            "borrowed_context_inclusive": ["withBorrowedReadContext"],
            "thread_local_inside_backup": ["ThreadLocal"],
            "delta_write_string": ["LmdbBackupDeltaCodec.writeString"],
            "native_data_lookup": ["NativeBackupWriter.data"],
            "native_write_bytes": ["NativeBackupWriter.writeBytes"],
            "native_write_literal": ["NativeBackupWriter.writeLiteral"],
            "chunk_encoder": ["LmdbBackupChunkCodec$Encoder.encode"],
            "crc": ["CRC32", "CRC32C"],
            "array_copy": ["Arrays.copyOf", "arraycopy", "copyMemoryToByteArray"],
            "record_snapshot": ["LmdbBackupRecordBuffer.snapshot"],
            "publication_payload": ["Stage.capturePublicationPayload"],
        }
        for component, values in patterns.items():
            if any(any(value in frame for value in values) for frame in frames):
                components[(operation, component)] += sample["count"]
    total = thread_totals[("main", "jdk.ExecutionSample")]
    user = condition["cpu"]["per_transaction_microseconds"]["main_user_seconds"]
    output.append({
        "condition": name,
        "main_java_samples": total,
        "main_backup_operations": [
            {"operation": operation, "samples": count, "sample_fraction": count / total,
             "heuristic_user_cpu_microseconds_per_transaction": user * count / total}
            for operation, count in operations.most_common()
        ],
        "nested_components": [
            {"operation": key[0], "component": key[1], "samples": count,
             "heuristic_user_cpu_microseconds_per_transaction": user * count / total}
            for key, count in components.most_common()
        ],
        "weighted_allocation_bytes_per_transaction_by_operation": {
            key: value / condition["measurement"]["transactions"] for key, value in operation_allocations.items()
        },
        "thread_sample_totals": [
            {"thread": key[0], "event": key[1], "count": value}
            for key, value in thread_totals.most_common()
            if key[1] in ("jdk.ExecutionSample", "jdk.NativeMethodSample")
        ],
        "background_java_self_samples": {
            thread: [{"frame": frame, "count": count} for frame, count in values.most_common(15)]
            for thread, values in background_self.items()
        },
    })
report = {
    "method": "Operation grouping follows caller stacks. Component counts are nested and cannot be summed.",
    "estimate_limit": "The optional microsecond estimate multiplies Java sample fraction by measured writer user CPU. "
                      "It assumes representative samples; it is not an independently timed per-operation measurement.",
    "conditions": output,
}
(ROOT / "component-attribution.json").write_text(json.dumps(report, indent=2) + "\n")
print(json.dumps({row["condition"]: row["main_backup_operations"] for row in output}, indent=2))

