import bisect
import collections
import json
from pathlib import Path

ROOT = Path('/workspace/scratch/11cb17cbd1fd/benchmarks/candidate-capture-fresh-profile')
report = {
    'method': 'Per native-thread first-to-last snapshots within measurement; identity is TID plus start ticks. CPU deltas use /proc clock ticks. Whole-window groups cover both endpoints. Any transient-thread deltas are lower bounds and listed separately. Transaction count is linearly interpolated from harness intervals at common endpoints. /proc syscw is write-family calls, not fsync calls.',
    'conditions': [],
}

for condition in ['off', 'on']:
    directory = ROOT / f'{ROOT.name}-n100-synctrue-{condition}-p1'
    result = json.loads((directory / 'result.json').read_text())
    phase = result['phases'][-1]
    phase_start = phase['started_epoch_millis'] / 1000
    phase_end = phase['finished_epoch_millis'] / 1000
    samples = [json.loads(line) for line in (directory / 'environment-samples.jsonl').read_text().splitlines()]
    samples = [s for s in samples if phase_start <= s['time_epoch_seconds'] <= phase_end]
    points = [(0, 0)]
    transactions = 0
    for interval in result['intervals']:
        transactions += interval['transactions']
        points.append((interval['elapsed_seconds'], transactions))
    points.append((result['measurement']['writer_seconds'], phase['transactions']))
    points.sort()
    elapsed = [p[0] for p in points]

    def transaction_at(epoch):
        t = epoch - phase_start
        index = bisect.bisect_right(elapsed, t) - 1
        if index < 0:
            return 0
        if index >= len(points) - 1:
            return phase['transactions']
        first, last = points[index:index + 2]
        return first[1] + (last[1] - first[1]) * (t - first[0]) / (last[0] - first[0])

    first_epoch = samples[0]['time_epoch_seconds']
    last_epoch = samples[-1]['time_epoch_seconds']
    covered_transactions = transaction_at(last_epoch) - transaction_at(first_epoch)
    histories = collections.defaultdict(list)
    for sample in samples:
        for thread in sample['thread_io']['threads'].values():
            if thread.get('available'):
                identity = (thread['native_tid'], thread['start_time_ticks'])
                histories[identity].append((sample['time_epoch_seconds'], thread,
                                            sample['thread_io']['clock_ticks_per_second']))
    groups = collections.defaultdict(collections.Counter)
    threads = []
    for identity, history in histories.items():
        if len(history) < 2:
            continue
        first, last = history[0], history[-1]
        a, b = first[1], last[1]
        name, role = a['comm'], a['role']
        if role in ['writer', 'publisher', 'cleanup', 'process_leader']:
            group = role
        elif name.startswith(('C1 Compiler', 'C2 Compiler')):
            group = 'compiler'
        elif name.startswith(('GC Thread', 'G1 ')):
            group = 'gc'
        elif name.startswith(('lmdb-direct-adj', 'lmdb-adjacency-')):
            group = 'adjacency'
        elif name.startswith('JFR '):
            group = 'profiler'
        else:
            group = 'other'
        full = first[0] == first_epoch and last[0] == last_epoch
        deltas = {
            'user_seconds': (b['user_cpu_ticks'] - a['user_cpu_ticks']) / first[2],
            'system_seconds': (b['system_cpu_ticks'] - a['system_cpu_ticks']) / first[2],
        }
        deltas.update({key: b['counters'][key] - value for key, value in a['counters'].items()})
        deltas['cpu_seconds'] = deltas['user_seconds'] + deltas['system_seconds']
        threads.append({'native_tid': identity[0], 'start_ticks': identity[1], 'comm': name,
                        'role': role, 'group': group, 'covers_common_endpoints': full,
                        'duration_seconds': last[0] - first[0], 'deltas': deltas})
        groups[group if full else group + '_partial'].update(deltas)
    report['conditions'].append({
        'condition': condition, 'first_epoch': first_epoch, 'last_epoch': last_epoch,
        'duration_seconds': last_epoch - first_epoch,
        'covered_transactions_interpolated': covered_transactions,
        'coverage_fraction': covered_transactions / phase['transactions'], 'threads': threads,
        'groups': {key: {'deltas': dict(values), 'per_covered_transaction': {
            name: value / covered_transactions for name, value in values.items()}}
            for key, values in groups.items()},
    })

(ROOT / 'thread-cost-analysis.json').write_text(json.dumps(report, indent=2) + '\n')

