package org.eclipse.rdf4j.sail.lmdb;

import java.io.PrintStream;
import java.lang.management.CompilationMXBean;
import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.lang.management.ThreadInfo;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Scratch diagnostic: unchanged public harness, fixed ABBA training and ABBA twice measurement. */
public final class BackupCrossoverDriver {
    private static final List<String> OWNED_PREFIXES = List.of("lmdb-direct-adjacency-", "Lmdb",
            "rdf4j-lmdb-", "rdf4j-value-overlay-warmup",
            "lmdb-paged-csf-build-");
    private static final CompilationMXBean COMPILER = ManagementFactory.getCompilationMXBean();

    public static void main(String[] args) throws Exception {
        if (args.length != 6 || !args[0].equals("--directory") || !args[2].equals("--runtime-jar")
                || !args[4].equals("--harness-jar")) {
            throw new IllegalArgumentException("Expected --directory PATH --runtime-jar PATH --harness-jar PATH");
        }
        Path root = Path.of(args[1]).toRealPath();
        Path runtime = Path.of(args[3]).toRealPath();
        Path harness = Path.of(args[5]).toRealPath();
        Map<String, String> sources = codeSources(runtime, harness);
        writeJson(root.resolve("code-sources.json"), sources);
        PrintStream launcher = System.out;
        boolean[] abba = { false, true, true, false };
        int ordinal = 0;
        for (int block = 0; block < 3; block++) {
            for (int index = 0; index < 4; index++) {
                boolean backup = abba[index];
                boolean training = block == 0;
                String label = training ? "crossover-fresh-n100-train0" + (index + 1) + (backup ? "-on" : "-off")
                        : "crossover-fresh-n100-b0" + block + "-w0" + (index + 1) + (backup ? "-on" : "-off");
                Map<String, Object> schedule = new LinkedHashMap<>();
                schedule.put("label", label);
                schedule.put("ordinal", ++ordinal);
                schedule.put("phase", training ? "training" : "measurement");
                schedule.put("backup", backup);
                schedule.put("block", block);
                schedule.put("pair", training ? 0 : (block - 1) * 2 + index / 2 + 1);
                run(root, runtime, harness, sources, schedule, launcher);
            }
        }
        launcher.println("CROSSOVER_COMPLETE,12");
        launcher.flush();
    }

    private static void run(Path root, Path runtime, Path harness, Map<String, String> sources,
            Map<String, Object> schedule, PrintStream launcher) throws Exception {
        String label = (String) schedule.get("label");
        boolean training = schedule.get("phase").equals("training");
        Path directory = Files.createDirectory(root.resolve(label));
        Path stores = Files.createDirectory(directory.resolve("stores"));
        if (!codeSources(runtime, harness).equals(sources)) {
            throw new IllegalStateException("Runtime CodeSource changed");
        }
        List<Map<String, Object>> beforeThreads = threads();
        if (!ownedThreads(beforeThreads).isEmpty()) {
            throw new IllegalStateException("Previous invocation retained owned workers: " + ownedThreads(beforeThreads));
        }
        List<String> arguments = List.of("--label", label, "--statements", "100", "--force-sync", "true",
                "--async-cleanup", "true", "--backup", schedule.get("backup").toString(), "--fresh-values", "true",
                "--warmup-rounds", "1", "--warmup-seconds", training ? "30" : "0",
                "--min-warmup-transactions", training ? "7500" : "0", "--measurement-seconds", training ? "1" : "30",
                "--pre-feature-parent", "false", "--native-commit-timing", "false", "--report-native-thread", "false",
                "--publication-observer", "publisher", "--directory", stores.toString(), "--keep-store", "false");
        launcher.println("CROSSOVER_START," + label + "," + ProcessHandle.current().pid());
        launcher.flush();
        Map<String, Object> metadata = new LinkedHashMap<>(schedule);
        metadata.put("arguments", arguments);
        metadata.put("code_sources", sources);
        metadata.put("thread_inventory_before", beforeThreads);
        List<GarbageCollectorMXBean> collectors = ManagementFactory.getGarbageCollectorMXBeans();
        List<long[]> gcBefore = new ArrayList<>();
        for (GarbageCollectorMXBean collector : collectors) {
            gcBefore.add(new long[] { collector.getCollectionCount(), collector.getCollectionTime() });
        }
        long heapBefore = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed();
        long compilerBefore = compilationMillis();
        long startedEpoch = System.currentTimeMillis();
        long started = System.nanoTime();
        long finished, finishedEpoch, heapAfter, compilerAfter;
        List<Map<String, Object>> afterThreads;
        List<Map<String, Object>> gc = new ArrayList<>();
        try (PrintStream output = new PrintStream(Files.newOutputStream(directory.resolve("console.log"),
                StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE), true, StandardCharsets.UTF_8)) {
            System.setOut(output);
            try {
                LmdbIncrementalBackupThroughputBenchmark.main(arguments.toArray(String[]::new));
            } catch (Exception | Error error) {
                error.printStackTrace(output);
                throw error;
            } finally {
                output.flush();
                System.setOut(launcher);
            }
            finished = System.nanoTime();
            finishedEpoch = System.currentTimeMillis();
            heapAfter = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed();
            compilerAfter = compilationMillis();
            afterThreads = threads();
            for (int index = 0; index < collectors.size(); index++) {
                GarbageCollectorMXBean collector = collectors.get(index);
                Map<String, Object> row = new LinkedHashMap<>();
                row.put("name", collector.getName());
                row.put("count_before", available(gcBefore.get(index)[0]));
                row.put("count_after", available(collector.getCollectionCount()));
                row.put("milliseconds_before", available(gcBefore.get(index)[1]));
                row.put("milliseconds_after", available(collector.getCollectionTime()));
                gc.add(row);
            }
        }
        Map<String, Object> invocation = new LinkedHashMap<>();
        invocation.put("process_id", ProcessHandle.current().pid());
        invocation.put("started_epoch_millis", startedEpoch);
        invocation.put("finished_epoch_millis", finishedEpoch);
        invocation.put("invocation_seconds", (finished - started) / 1e9);
        invocation.put("heap_before_bytes", heapBefore);
        invocation.put("heap_after_bytes", heapAfter);
        invocation.put("live_threads_before", beforeThreads.size());
        invocation.put("live_threads_after", afterThreads.size());
        invocation.put("gc_count_delta", totalDelta(gc, "count"));
        invocation.put("gc_milliseconds_delta", totalDelta(gc, "milliseconds"));
        invocation.put("invocation_compilation_milliseconds", compilerBefore < 0 || compilerAfter < 0
                ? null : compilerAfter - compilerBefore);
        metadata.put("invocation", invocation);
        metadata.put("gc_collectors", gc);
        metadata.put("thread_inventory_after", afterThreads);
        long quiescenceStart = System.nanoTime();
        List<Map<String, Object>> remaining = ownedThreads(afterThreads);
        while (!remaining.isEmpty() && System.nanoTime() - quiescenceStart < 10_000_000_000L) {
            Thread.sleep(25);
            remaining = ownedThreads(threads());
        }
        Map<String, Object> quiescence = new LinkedHashMap<>();
        quiescence.put("completed", remaining.isEmpty());
        quiescence.put("timeout_seconds", 10);
        quiescence.put("wait_seconds", (System.nanoTime() - quiescenceStart) / 1e9);
        quiescence.put("remaining_lmdb_threads", remaining);
        metadata.put("quiescence", quiescence);
        metadata.put("validated", false);
        writeJson(directory.resolve("window-raw.json"), metadata);
        if (!remaining.isEmpty()) {
            throw new IllegalStateException("Per-store workers did not quiesce after close: " + remaining);
        }
        launcher.println("CROSSOVER_FINISHED," + label);
        launcher.flush();
    }

    private static Long available(long value) { return value < 0 ? null : value; }

    private static Long totalDelta(List<Map<String, Object>> rows, String key) {
        long total = 0;
        for (Map<String, Object> row : rows) {
            Long before = (Long) row.get(key + "_before"), after = (Long) row.get(key + "_after");
            if (before == null || after == null) return null;
            total += after - before;
        }
        return total;
    }

    private static long compilationMillis() {
        return COMPILER != null && COMPILER.isCompilationTimeMonitoringSupported() ? COMPILER.getTotalCompilationTime() : -1;
    }

    private static List<Map<String, Object>> threads() {
        var bean = ManagementFactory.getThreadMXBean();
        List<Map<String, Object>> result = new ArrayList<>();
        for (ThreadInfo thread : bean.getThreadInfo(bean.getAllThreadIds())) {
            if (thread == null) continue;
            Map<String, Object> row = new LinkedHashMap<>();
            row.put("id", thread.getThreadId());
            row.put("name", thread.getThreadName());
            row.put("state", thread.getThreadState().toString());
            row.put("daemon", thread.isDaemon());
            result.add(row);
        }
        result.sort(Comparator.comparingLong(row -> (Long) row.get("id")));
        return result;
    }

    private static List<Map<String, Object>> ownedThreads(List<Map<String, Object>> threads) {
        return threads.stream().filter(row -> OWNED_PREFIXES.stream()
                .anyMatch(prefix -> ((String) row.get("name")).startsWith(prefix))).toList();
    }

    private static Map<String, String> codeSources(Path runtime, Path harness) throws Exception {
        Map<String, String> result = new LinkedHashMap<>();
        for (Class<?> type : List.of(LmdbStore.class, LmdbBackupChunkCodec.class, ValueStore.class,
                TripleStore.class, LmdbBackupOutbox.class, LmdbBackupRecordBuffer.class,
                LmdbBackupDeltaCodec.class,
                Class.forName("org.eclipse.rdf4j.sail.lmdb.LmdbBackupRecordBuffer$MemoryOutput", false,
                        LmdbBackupRecordBuffer.class.getClassLoader()),
                LmdbIncrementalBackupThroughputBenchmark.class)) {
            Path location = Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath();
            Path expected = type == LmdbIncrementalBackupThroughputBenchmark.class ? harness : runtime;
            if (!location.equals(expected)) throw new IllegalStateException(type.getName() + " loaded from " + location);
            result.put(type.getName(), location.toString());
        }
        return result;
    }

    private static void writeJson(Path path, Object value) throws Exception {
        Path temporary = path.resolveSibling(path.getFileName() + ".tmp");
        Files.writeString(temporary, json(value) + "\n", StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
        Files.move(temporary, path, StandardCopyOption.ATOMIC_MOVE);
    }

    private static String json(Object value) {
        if (value == null) return "null";
        if (value instanceof String string) {
            StringBuilder output = new StringBuilder("\"");
            for (int index = 0; index < string.length(); index++) {
                char ch = string.charAt(index);
                if (ch == '\\' || ch == '\"') output.append('\\').append(ch);
                else if (ch < 32) output.append(String.format("\\u%04x", (int) ch));
                else output.append(ch);
            }
            return output.append('\"').toString();
        }
        if (value instanceof Number || value instanceof Boolean) return value.toString();
        if (value instanceof Map<?, ?> map) {
            List<String> parts = new ArrayList<>();
            map.forEach((key, item) -> parts.add(json(key.toString()) + ":" + json(item)));
            return "{" + String.join(",", parts) + "}";
        }
        if (value instanceof List<?> list) return "[" + String.join(",", list.stream().map(BackupCrossoverDriver::json).toList()) + "]";
        throw new IllegalArgumentException("Unsupported JSON value: " + value.getClass());
    }
